alter table public.vehicle_image_assets add column if not exists file_format_status text; alter table public.vehicle_image_assets add constraint vehicle_image_assets_file_format_status_check check (file_format_status is null or file_format_status in ('native_png','base64_text_not_png')); comment on column public.vehicle_image_assets.file_format_status is 'GitHub blob payload format inspection; native_png was decoded and viewed; base64_text_not_png means the .png blob contains base64 text rather than PNG binary.'
